#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="${ENV_FILE:-deploy/.cloudflare.env}"
TOTAL_STAGES=8

banner "Cloudflare cutover — 91skylineworks.com"

say "MilesWeb stays the live site until we deploy the Worker later."
say "Do not cancel MilesWeb. Do not delete A/CNAME records yet."
note "Saved values: $ENV_FILE  (gitignored). Ctrl-C anytime; re-run to resume."
pause "Press Enter for stage 1."

# ── 1. Account ────────────────────────────────────────────────────────────
stage "Cloudflare account"
say "Need a free Cloudflare account. Skip ahead if you already have one."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up with email (or Google). Confirm the verification email."
step "If you already have an account: https://dash.cloudflare.com/login"
pause "Logged into the Cloudflare dashboard?"

# ── 2. Add domain ─────────────────────────────────────────────────────────
stage "Add 91skylineworks.com"
say "This imports today's DNS so the site keeps working on MilesWeb."
open_url "https://dash.cloudflare.com/"
step "Click Onboard a domain."
step "Enter: 91skylineworks.com"
step "Let Cloudflare scan existing DNS records (do not start from a blank zone)."
step "Choose the Free plan → Continue."
step "Review the scanned records. Keep A / CNAME that point at MilesWeb."
step "Keep existing MX for now (cPanel mail still works until Email Routing)."
step "Continue until Cloudflare shows two nameservers like:"
note "    something.ns.cloudflare.com"
note "    somethingelse.ns.cloudflare.com"
ask CF_NS1 "Paste nameserver 1:"
ask CF_NS2 "Paste nameserver 2:"
write_env CF_NS1 "$CF_NS1"
write_env CF_NS2 "$CF_NS2"
write_env CF_ZONE "91skylineworks.com"

# ── 3. Registrar ──────────────────────────────────────────────────────────
stage "Who is the registrar?"
say "Nameservers are changed at the registrar, not in MilesWeb cPanel (unless they are the same)."
open_url "https://lookup.icann.org/en/lookup"
step "Search: 91skylineworks.com"
step "Note the Registrar name (MilesWeb, GoDaddy, Namecheap, PublicDomainRegistry, …)."
ask REGISTRAR "Registrar name:"
write_env REGISTRAR "$REGISTRAR"
say "Log into that registrar next. If you only have MilesWeb cPanel, look for"
say "Domain → Nameservers, or a separate 'Domain Registration' login."

# ── 4. Nameservers ────────────────────────────────────────────────────────
stage "Point nameservers at Cloudflare"
warn "Do this only after stage 2 imported the MilesWeb A records."
warn "If DNSSEC is ON at the registrar, turn it OFF first or the domain can go dark."
say "At the registrar DNS / nameserver page:"
step "Turn off DNSSEC if it is enabled. Save."
step "Remove the old nameservers (MilesWeb / the current pair)."
step "Add exactly these two:"
note "    $CF_NS1"
note "    $CF_NS2"
step "Save. Registrars can take minutes to 24 hours."
if ! confirm "DNSSEC is off and both Cloudflare nameservers are saved at the registrar?"; then
  warn "Stop here. Re-run this wizard after the nameserver change."
  SKIPPED+=("nameserver change at $REGISTRAR")
  finish
  exit 0
fi
write_env NS_UPDATED "yes"

# ── 5. Wait until Active ──────────────────────────────────────────────────
stage "Wait until the zone is Active"
open_url "https://dash.cloudflare.com/"
step "Open 91skylineworks.com → Overview."
step "Status must read Active. Cloudflare also emails you."
note "Usually minutes; can take up to 24 hours. Ctrl-C and re-run if still Pending."
ask ZONE_STATUS "Type Active when the Overview says Active:"
write_env ZONE_STATUS "$ZONE_STATUS"
if [[ ! "$ZONE_STATUS" =~ [Aa]ctive ]]; then
  warn "Zone is not Active yet. Re-run the wizard from here once it is."
  SKIPPED+=("zone still pending — skip Email Routing / tokens until Active")
  finish
  exit 0
fi

# ── 6. Email Routing ──────────────────────────────────────────────────────
stage "Forward contact@ to your inbox"
warn "This replaces MilesWeb MX. cPanel webmail for contact@ / website@ stops."
warn "Inbound mail will land in the Gmail (or other) address you verify here."
say "Site contact form still sends via MilesWeb SMTP until we deploy the Worker."
if ! confirm "Ready to move inbound mail off MilesWeb now?"; then
  SKIPPED+=("Email Routing — do this before cancelling MilesWeb")
else
  open_url "https://dash.cloudflare.com/?to=/:account/email/routing"
  step "Compute → Email Service → Email Routing → select 91skylineworks.com."
  step "Onboard Domain (or Add records and enable). Confirm the MX / SPF / DKIM it will add."
  step "If it asks to delete existing (MilesWeb) MX records — yes, Email Routing needs exclusive MX."
  step "Routing Rules → Create routing rule:"
  note "    Email pattern: contact"
  note "    Action: Send to an email"
  note "    Destination: your Gmail (or whatever inbox you actually read)"
  step "Save. Open that inbox, click Verify email address in Cloudflare's message."
  step "Optional: add website as another custom address to the same inbox."
  ask MAIL_FORWARD_TO "Paste the destination inbox (verified):"
  write_env MAIL_FORWARD_TO "$MAIL_FORWARD_TO"
  write_env MAIL_LOCAL_PART "contact"
fi

# ── 7. API token ──────────────────────────────────────────────────────────
stage "API token + Account ID"
say "This lets us deploy the Worker, D1 database, and R2 uploads from this repo."
open_url "https://dash.cloudflare.com/"
step "Click 91skylineworks.com. Right sidebar (or Overview): copy Account ID."
note "Also in the dashboard URL: dash.cloudflare.com/<ACCOUNT_ID>/..."
ask CLOUDFLARE_ACCOUNT_ID "Paste Account ID:"
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
open_url "https://dash.cloudflare.com/"
step "Open 91skylineworks.com → Overview → copy Zone ID (right column)."
ask CF_ZONE_ID "Paste Zone ID:"
write_env CF_ZONE_ID "$CF_ZONE_ID"

open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token."
step "Use template: Edit Cloudflare Workers → Use template."
step "Add two extra permissions (Add more → Account):"
note "    Account · D1 · Edit"
note "    Account · Workers R2 Storage · Edit"
step "Account resources: Include → your account. Zone resources: Include → 91skylineworks.com."
step "Continue to summary → Create Token. Copy the token now — it is shown once."
ask_secret CLOUDFLARE_API_TOKEN "Paste the API token:"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"

# ── 8. Resend (outbound form mail) ────────────────────────────────────────
stage "Resend — send form emails"
say "Cloudflare Email Routing only receives. Form notifications need a send API."
say "Free Resend account. From-address stays website@91skylineworks.com."
open_url "https://resend.com/signup"
step "Create a free account and confirm email."
open_url "https://resend.com/domains"
step "Add Domain → 91skylineworks.com. Do not turn on Receiving (inbound is Cloudflare)."
step "Click Sign in to Cloudflare and authorize — it writes DKIM/SPF for you."
step "If it asks you to add records by hand: DNS Only (grey cloud), never orange-proxied."
step "If two SPF TXT records appear on @ (root), tell me — we merge them. Do not leave duplicates."
step "Click Verify DNS Records. Wait until status is Verified (often a few minutes)."
open_url "https://resend.com/api-keys"
step "Create API Key. Name: 91skylineworks. Permission: Sending access."
step "Copy the key (starts re_)."
ask_secret RESEND_API_KEY "Paste the Resend API key:"
write_env RESEND_API_KEY "$RESEND_API_KEY"
write_env MAIL_FROM "website@91skylineworks.com"
write_env MAIL_TO "contact@91skylineworks.com"

say ""
say "While still on MilesWeb: npm run cf:resend-php"
say "Paste resend_api_key into server public_html/api/config.php and upload mail.php."

say ""
say "Dashboard work is done. Next (I do this): Worker + D1 + R2, then switch the live origin."
warn "Leave MilesWeb running. Do not delete the hosting plan yet."

finish
